new_weeks=[('Work like a developer','Terminal, environments, Git, and CLI boundaries','Developer tools'),('Test and debug deliberately','Regression tests, errors, types, and fakes','Engineering'),('Handle real-world data','Regex, dates, money, and rejection reports','Data'),('Store and query data','SQLite, joins, aggregation, and parameters','Databases'),('Talk to services','HTTP, URL encoding, pagination, and retries','APIs'),('Design maintainable Python','Defaults, objects, iterators, configuration','Engineering'),('Broaden your problem-solving toolkit','Recursion, graphs, linked lists, and heaps','Interviews'),('Build a small backend','Resource contracts, validation, access, updates','Backend'),('Make automation dependable','Logs, reruns, filenames, and batch reports','Automation'),('Maintain and collaborate','Read code, adapt schemas, review, triage','Team practice'),('Ship and verify your work','CLI, API, continuous checks, clean handoff','Portfolio'),('Practice the entry-level transition','Unseen tasks, take-home changes, explanation','Readiness')]
